package com.foodresq.matchingservice.controller; import com.foodresq.matchingservice.entity.FoodMatch; import com.foodresq.matchingservice.service.MatchingService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/matching") @CrossOrigin public class MatchingController{private final MatchingService s;public MatchingController(MatchingService s){this.s=s;}@PostMapping("/find/{id}")public List<FoodMatch> find(@PathVariable String id){return s.find(id);}@GetMapping("/{id}")public List<FoodMatch> get(@PathVariable String id){return s.get(id);}}